#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

Node *new_node(int v) {
    Node *n = malloc(sizeof *n);
    if (!n) return NULL;
    n->val = v; n->next = NULL;
    return n;
}

void push_front(Node **head, int v) {
    Node *n = new_node(v);
    if (!n) return;
    n->next = *head;          /* link to the rest first */
    *head = n;
}

void push_back(Node **head, int v) {
    Node *n = new_node(v);
    if (!n) return;
    Node **pp = head;
    while (*pp) pp = &(*pp)->next;   /* find the NULL link */
    *pp = n;
}

int delete_value(Node **head, int v) {
    for (Node **pp = head; *pp; pp = &(*pp)->next) {
        if ((*pp)->val == v) {
            Node *dead = *pp;
            *pp = dead->next;        /* bypass */
            free(dead);
            return 1;
        }
    }
    return 0;
}

void print_list(const Node *h) {
    for (; h; h = h->next) printf("%d -> ", h->val);
    puts("NULL");
}

Node *reverse(Node *head) {
    Node *prev = NULL, *cur = head;
    while (cur) {
        Node *nxt = cur->next;   /* save the rest */
        cur->next = prev;        /* flip the link */
        prev = cur;
        cur = nxt;
    }
    return prev;
}

Node *cycle_start(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) {
                slow = slow->next;
                fast = fast->next;
            }
            return slow;
        }
    }
    return NULL;
}

void free_list(Node **head) {
    Node *cur = *head;
    while (cur) {
        Node *nxt = cur->next;   /* read before free */
        free(cur);
        cur = nxt;
    }
    *head = NULL;
}
